typedef struct { void (*fn)(const event_t *, void *); void *ctx; } sub_t;
typedef struct { sub_t *v; size_t n, cap; } channel_t;

void hub_subscribe(channel_t *ch, void (*fn)(const event_t *, void *), void *ctx);

void hub_publish(channel_t *ch, const event_t *e)
{
    sub_t snapshot[64];                       /* copy first: handlers may (un)subscribe */
    size_t n = hub_snapshot(ch, snapshot, 64);
    for (size_t i = 0; i < n; i++) snapshot[i].fn(e, snapshot[i].ctx);
}
